OLD=MEDIA/'05_Reels/ShapesSeries_20261114/L21'
NEW='ArrowSwarm_Ahtapot_CreativeShort_TR.mp4'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

PAGE=r'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Arrow Swarm · 16 saniyelik yaratıcı kurgu</title><style>
:root{color-scheme:dark;--navy:#08162b;--ink:#102d48;--edge:#305573;--text:#f1f8ff;--soft:#b3cce1;--cyan:#68dbff;--gold:#ffdc65}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 95% 0,#173e61,transparent 54%),var(--navy);color:var(--text);font:16px/1.55 system-ui,-apple-system,sans-serif}main{max-width:1050px;margin:auto;padding:28px 24px 44px}.eyebrow{font-size:12px;letter-spacing:.14em;font-weight:800;color:var(--cyan)}h1{font-size:clamp(30px,5vw,48px);line-height:1.07;margin:10px 0 14px}h2{font-size:21px;margin:0 0 12px}p{margin:7px 0 18px;color:var(--soft)}.intro{max-width:820px}.tags{display:flex;flex-wrap:wrap;gap:7px;margin:18px 0 25px}.tag{font-size:12px;padding:4px 10px;border:1px solid var(--edge);border-radius:100px;color:#d9edff}.tag.gold{color:var(--gold);border-color:#8a793d}.layout{display:grid;grid-template-columns:minmax(260px,385px) minmax(0,1fr);gap:30px;align-items:start}.player-column{min-width:0}.versions,.controls,.chapters,.links{display:flex;gap:8px;flex-wrap:wrap}button,a.button{display:inline-flex;justify-content:center;align-items:center;gap:6px;min-height:44px;border:1px solid var(--edge);border-radius:12px;background:#173954;color:var(--text);font:inherit;line-height:1.35;padding:10px 12px;cursor:pointer;text-decoration:none}button:hover,a.button:hover{border-color:var(--cyan);background:#225276}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.versions{margin-bottom:13px}.versions button{flex:1;font-size:14px;min-width:140px}.versions button[aria-pressed=true]{background:linear-gradient(135deg,#086b91,#12457b);border-color:var(--cyan);box-shadow:inset 0 -3px #4ccefa;color:var(--gold);font-weight:800}.video-wrap{display:flex;justify-content:center}video{display:block;aspect-ratio:9/16;width:min(100%,42vh);height:auto;background:#020a15;border:1px solid #48647c;border-radius:18px;box-shadow:0 20px 60px #0005}.controls{justify-content:center;margin:15px auto 0}.controls .primary{background:linear-gradient(#43d9ff,#0aa3dc);color:#041b32;border-color:#8eeaff;font-weight:800}.transport{max-width:360px;margin:12px auto 0}.transport input{width:100%;height:24px;accent-color:var(--cyan);cursor:pointer}.clock{display:block;text-align:center;font-variant-numeric:tabular-nums;color:var(--cyan);font-size:14px}.card{border:1px solid var(--edge);border-radius:18px;padding:22px;background:linear-gradient(145deg,#12334f,#10243c);margin-bottom:17px}.card p:last-child{margin-bottom:0}.chapters button,.links a{font-size:14px}.links{margin-top:17px}.steps{padding-left:20px;color:#c9dff1;margin:10px 0 15px}.steps li{padding:4px 0}.steps strong{color:var(--gold)}.small{font-size:13px;color:#97b5ce}.status{min-height:22px;color:var(--gold);font-size:13px;margin:10px 0 0}.store{background:linear-gradient(135deg,#20bbf5,#0965d2)!important;border-color:#8ae5ff!important;box-shadow:0 0 0 2px #dba83c;font-weight:800}.notice{border-left:3px solid var(--gold);padding-left:14px}footer{color:#7f9fba;font-size:12px;margin-top:24px}code{color:var(--cyan)}@media(max-width:740px){main{padding:24px 16px 35px}.layout{grid-template-columns:1fr;gap:24px}.player-column{max-width:390px;width:100%;margin:auto}video{width:min(100%,43vh)}.card{padding:18px}.versions button{min-width:0;font-size:13px}.controls button{padding:10px 11px}}
</style></head><body><main><header class="intro"><div class="eyebrow">ARROW SWARM / YARATICI KURGU 01</div><h1>44 ok. 16 saniye.</h1><p>İlk hamleni seç. Cevabı gör. Ahtapotun çözülüşünü tek bir hızlı akışta izle.</p><div class="tags"><span class="tag gold">%61,3 daha kısa</span><span class="tag">1080 × 1920 · 30 fps</span><span class="tag">Gerçek Unity görüntüsü</span></div></header>
<div class="layout"><section class="player-column" aria-label="Video karşılaştırması"><div class="versions" aria-label="Kurgu seçimi"><button id="new" aria-pressed="true">Yeni kurgu · 16s</button><button id="old" aria-pressed="false">Önceki · 41,3s</button></div><div class="video-wrap"><video id="reel" playsinline preload="metadata" poster="cover.jpg" aria-label="Yeni 16 saniyelik ahtapot Reels videosu"></video></div><div class="controls"><button class="primary" id="play">▶ Sesli oynat</button><button id="pause">Duraklat</button><button id="mute" aria-pressed="false">Sesi kapat</button></div><div class="transport"><input type="range" id="seek" min="0" max="16" step="0.1" value="0" aria-label="Videoda zaman seç"><output id="clock" class="clock">0,0 / 16,0 s</output></div><p id="player-status" role="status" class="status"></p></section>
<div><section class="card"><div class="eyebrow" id="version-label">YENİ KURGU</div><h2 id="version-title">Kısa, net, ritimli.</h2><p id="version-description">Uzun çözüm bölümü 7,4× hızlandı. İlk doğru hamle ve sonucun tadı gerçek hızda kaldı.</p><div class="chapters" id="chapters" aria-label="Video bölümleri"></div><div class="links"><a class="button" href="__NEW__" download>↓ Yeni MP4 indir</a><a class="button" href="before.mp4" download>Önceki MP4</a><a class="button" href="captions_TR.srt" download>Altyazı · SRT</a><a class="button" href="encoded_contact_sheet.jpg">Kurgu kareleri</a><a class="button" href="QA_REPORT.json">Teknik kontrol</a></div></section>
<section class="card"><h2>Yeni akış</h2><ol class="steps"><li><strong>0–3,5s</strong> · 44 ok, iki seçenek, kısa karar anı.</li><li><strong>3,5–5s</strong> · Doğru A oku gerçek hızda çıkar.</li><li><strong>5–7,6s</strong> · Kalan çözüm 7,4× hızlanır.</li><li><strong>7,6–11,6s</strong> · Son atış ve üç yıldızlı sonuç gerçek hızda.</li><li><strong>11,6–16s</strong> · Kısa marka ve Play Now kapanışı.</li></ol><p class="small">44 okun tamamı gerçek kaynak kaydından gelir. İki HUD korunur; 7,4× işareti yalnız hızlanan orta bölümde görünür. Yazılar, işaretler, tempo, konuşma ve ses vurguları kurguya eklenmiştir.</p></section>
<section class="card"><h2>Oynamak ister misin?</h2><a class="button store" href="#mock-store" id="store">▶ PLAY NOW</a><p class="small" style="margin-top:14px">MOCK · Mağaza henüz yayınlanmadı. Videodaki basma hareketi tanıtım animasyonudur.</p><p role="status" id="store-status" class="status" hidden>Mock bağlantı test edildi. Gerçek Google Play adresi yayınlanınca eklenecek.</p></section><p class="small notice">Önceki kurgu ayrı tutuldu. Üstteki iki seçenek aynı oynatıcıda doğrudan karşılaştırma yapar. Oyun sahnelerine ve mekaniklere değişiklik yok.</p></div></div><footer>Farzetki Games · Yerel inceleme · Otomatik oynatma ve dışarıya yayın yok.</footer></main>
<script>
'use strict';const configs={new:{file:'__NEW__',duration:16,poster:'cover.jpg',label:'YENİ KURGU',title:'Kısa, net, ritimli.',description:'Uzun çözüm bölümü 7,4× hızlandı. İlk doğru hamle ve sonucun tadı gerçek hızda kaldı.',aria:'Yeni 16 saniyelik ahtapot Reels videosu',chapters:[['Açılış',0],['Seçim',1.8],['Cevap',3.5],['Hızlı çözüm',5],['Sonuç',9.4],['Tanıtım',12.4]]},old:{file:'before.mp4',duration:41.3,poster:'',label:'ÖNCEKİ KURGU',title:'Önceki 41,3 saniyelik sürüm.',description:'Aynı bölümün önceki kurgusu; yeni videoyla karşılaştırmak için aynen korundu.',aria:'Önceki 41,3 saniyelik ahtapot Reels videosu',chapters:__OLD_CHAPTERS__}};
const v=document.getElementById('reel'),seek=document.getElementById('seek'),clock=document.getElementById('clock'),status=document.getElementById('player-status');let selected='new';const fmt=n=>Number(n).toFixed(1).replace('.',',');function duration(){return Number.isFinite(v.duration)?v.duration:configs[selected].duration}function update(){clock.textContent=fmt(v.currentTime)+' / '+fmt(duration())+' s';seek.max=duration();seek.value=v.currentTime;seek.setAttribute('aria-valuetext',fmt(v.currentTime)+' saniye')}function select(key){selected=key;const c=configs[key];v.pause();status.textContent='';v.src=c.file;v.poster=c.poster;v.setAttribute('aria-label',c.aria);v.load();for(const name of ['new','old'])document.getElementById(name).setAttribute('aria-pressed',String(name===key));for(const [id,value] of [['version-label',c.label],['version-title',c.title],['version-description',c.description]])document.getElementById(id).textContent=value;const chapters=document.getElementById('chapters');chapters.replaceChildren();c.chapters.forEach(([text,time])=>{const b=document.createElement('button');b.type='button';b.textContent=text;b.dataset.time=time;b.onclick=()=>{v.pause();v.currentTime=Math.min(time,duration()-.1);update()};chapters.append(b)});update()}
document.getElementById('new').onclick=()=>select('new');document.getElementById('old').onclick=()=>select('old');document.getElementById('play').onclick=async()=>{try{v.muted=false;syncMute();await v.play();status.textContent=''}catch(error){status.textContent='Video oynatılamadı. MP4 indir bağlantısını da kullanabilirsin.'}};document.getElementById('pause').onclick=()=>v.pause();function syncMute(){const b=document.getElementById('mute');b.textContent=v.muted?'Sesi aç':'Sesi kapat';b.setAttribute('aria-pressed',String(v.muted))}document.getElementById('mute').onclick=()=>{v.muted=!v.muted;syncMute()};seek.addEventListener('input',()=>{v.currentTime=Number(seek.value);update()});for(const event of ['timeupdate','loadedmetadata','durationchange'])v.addEventListener(event,update);v.addEventListener('volumechange',syncMute);v.addEventListener('error',()=>{status.textContent='Video dosyası yüklenemedi. MP4 indir bağlantısını kontrol edebilirsin.'});document.getElementById('store').onclick=e=>{e.preventDefault();document.getElementById('store-status').hidden=false};select('new');
</script></body></html>'''

def main():
    OUT.mkdir(parents=True,exist_ok=True)
    source=OLD/'ArrowSwarm_Shapes21_TR.mp4';qa=json.loads((OLD/'QA_REPORT.json').read_text(encoding='utf-8'))
    assert sha(source)==qa['sha256'],'Before source differs from current verified original'
    before=OUT/'before.mp4';shutil.copy2(source,before);assert sha(before)==sha(source)
    plan=json.loads((OLD/'edit_plan.json').read_text(encoding='utf-8'))
    chapters=[['Soru',2.6],['Cevap',plan['first_fire']],['Kalan oklar',plan['rest_start']],['Sonuç',plan['win_voice_start']],['Tanıtım',plan['outro_start']+.5]]
    page=PAGE.replace('__NEW__',NEW).replace('__OLD_CHAPTERS__',json.dumps(chapters,ensure_ascii=False))
    (OUT/'index.html').write_text(page,encoding='utf-8')
    assert page.count('<video ')==1 and '<video controls' not in page and 'autoplay' not in page
    print(json.dumps({'gallery':str(OUT/'index.html'),'beforeSha256':sha(before),'beforeByteIdentical':True,'newDuration':16,'oldDuration':41.3,'shorterPercent':round((1-16/41.3)*100,1),'onePlayer':True,'nativeControls':False},ensure_ascii=True,indent=2))
if __name__=='__main__':main()
